-- GENERATED by scripts/db_export_schema.py from the live database. Do not hand-edit.
CREATE OR REPLACE FUNCTION digest.fb_thread(p_phone text, p_author text DEFAULT NULL::text, p_terms text[] DEFAULT '{}'::text[], p_post_id text DEFAULT NULL::text, p_limit_comments integer DEFAULT 60)
 RETURNS TABLE(kind text, author text, body text, occurred_at timestamp with time zone, url text, image_text text, post_id text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'digest', 'pg_temp'
AS $function$
declare
  v_n int; v_post text; v_post_author text;
begin
  select case when digest.resolve_asker(p_phone) is not null then 1 else 0 end into v_n;
  if v_n < 1 then return; end if;

  if p_post_id is not null then
    select ci.source_id into v_post from digest.content_items ci
    where ci.source = 'fb_post' and ci.source_id = p_post_id
      and ci.sensitivity not in ('never_surface', 'restricted')
      and ci.access_rule->>'type' = 'public';
  else
    -- best thread: author and/or terms; prefer rows matching BOTH, then most terms, then recency
    select ci.source_id into v_post
    from digest.content_items ci
    where ci.source = 'fb_post'
      and ci.sensitivity not in ('never_surface', 'restricted')
      and ci.access_rule->>'type' = 'public'
      and (p_author is null
           or digest.name_fold(ci.meta->>'author_name') like '%' || digest.name_fold(p_author) || '%')
      and (coalesce(cardinality(p_terms), 0) = 0
           or exists (select 1 from unnest(p_terms) t
                      where ci.body ilike '%' || digest.content_like_escape(t) || '%'
                         or ci.tl_dr ilike '%' || digest.content_like_escape(t) || '%'
                         or ci.search_extra ilike '%' || digest.content_like_escape(t) || '%'))
    order by
      (select count(*) from unnest(p_terms) t
       where ci.body ilike '%' || digest.content_like_escape(t) || '%'
          or ci.tl_dr ilike '%' || digest.content_like_escape(t) || '%'
          or ci.search_extra ilike '%' || digest.content_like_escape(t) || '%') desc,
      ci.occurred_at desc
    limit 1;
    -- author+terms found nothing -> relax to author-only newest (their latest thread)
    if v_post is null and p_author is not null then
      select ci.source_id into v_post
      from digest.content_items ci
      where ci.source = 'fb_post'
        and ci.sensitivity not in ('never_surface', 'restricted')
        and ci.access_rule->>'type' = 'public'
        and digest.name_fold(ci.meta->>'author_name') like '%' || digest.name_fold(p_author) || '%'
      order by ci.occurred_at desc limit 1;
    end if;
  end if;

  if v_post is null then return; end if;

  select ci.meta->>'author_name' into v_post_author
  from digest.content_items ci
  where ci.source = 'fb_post' and ci.source_id = v_post;

  return query
  select 'post'::text, ci.meta->>'author_name', ci.body, ci.occurred_at, ci.url,
         nullif(trim(split_part(coalesce(ci.search_extra,''), '[IMAGE TEXT]', 2)), ''), ci.source_id
  from digest.content_items ci
  where ci.source = 'fb_post' and ci.source_id = v_post;

  return query
  select 'comment'::text, ci.meta->>'author_name',
         -- #39: a reply OPENING with the post author's name is addressing them — mark it,
         -- exactly like content_search_v2 does (exact char-prefix compare, never LIKE).
         case when v_post_author is not null and length(v_post_author) >= 3
                   and lower(left(ci.body, length(v_post_author))) = lower(v_post_author)
              then '[→ to ' || v_post_author || '] '
                   || ltrim(substr(ci.body, length(v_post_author) + 1), ' -–—,:;.!')
              else ci.body end,
         ci.occurred_at, ci.url,
         null::text, v_post
  from digest.content_items ci
  where ci.source = 'fb_comment' and ci.meta->>'post_id' = v_post
    and ci.sensitivity not in ('never_surface', 'restricted')
  order by ci.occurred_at asc
  limit greatest(coalesce(p_limit_comments, 60), 0);
end $function$
